mapper.select:

SELECT
  count(*) totcnt
FROM
  ttokssaemdb.member member,
  ttokssaemdb.branch branch
WHERE
  member.branchid = branch.branchid

    AND member.branchid = #{session_branchid}


    AND member.type = #{type}


    AND member.classyn = #{classyn}


    AND (
      member.membername LIKE #{likeQuery}
      OR
      member.contact LIKE #{likeQuery}
    )

SELECT branch.branchid, branch.branchname, member.memberno, member.memberid, member.type, member.membername, member.schoolcode, member.schoolname, member.grade, member.gender, member.contact, member.email, member.os, member.pushtoken, member.marketing, member.push, member.classyn, DATE_FORMAT(member.classexpiredate, '%Y-%m-%d') classexpiredate, IFNULL((SELECT SUM(point) FROM blackmark WHERE memberid = member.memberid AND cancelyn = 'N'),0) total_blackmark, IFNULL((SELECT SUM(point) FROM blackmark WHERE memberid = member.memberid AND cancelyn = 'N' AND ( regdate > LAST_DAY(NOW() - interval 1 month) AND regdate <= LAST_DAY(NOW()) )), 0) month_blackmark, IFNULL((SELECT stopyn FROM vocaplan WHERE memberid = member.memberid), '-') stopyn, DATE_FORMAT(member.regdate, '%Y-%m-%d %H:%i:%s') regdate FROM ttokssaemdb.member member, ttokssaemdb.branch branch
AND member.branchid = branch.branchid
AND member.branchid = #{session_branchid}
AND member.type = #{type}
AND member.classyn = #{classyn}
AND ( member.membername LIKE #{likeQuery} OR member.contact LIKE #{likeQuery} )
member.regdate branch.branchname member.membername member.type member.schoolcode member.schoolname member.grade member.contact member.email member.os member.marketing member.push member.classexpiredate month_blackmark member.regdate DESC ASC DESC
LIMIT ${length} OFFSET ${start}
